var SH={db:null,seeded:{},pending:{},busy:{},applying:false,warned:false,edit:false};
var SHMAP={"recab_records_v1":"records","recab_opts_v1":"opts","recab_users_v1":"users"};
function syncOut(k,v){var n=SHMAP[k];if(!n||!SH.db||SH.applying)return;SH.pending[n]={v:v};if(SH.busy[n])return;SH.busy[n]=true;
 (async function(){try{while(SH.pending[n]){var val=SH.pending[n];delete SH.pending[n];
  try{await SH.db.doc("tracker/"+n).set({v:val.v})}catch(e){if(!SH.warned){SH.warned=true;toast("Saved on this device only: you don't have permission to change shared data")}}}}finally{SH.busy[n]=false}})()}
const HEADERS=["DATE TURNOVER","ACCOUNTABLE TO","DESTINATION","EQUIPMENT / MATERIALS","BRAND / MODEL","SERIAL NO.","STATUS","REMARKS","DATE ISSUED","REPAIR HISTORY","CALIBRATION HISTORY"];
const SEED=[{"DATE TURNOVER":"2026-10-10","ACCOUNTABLE TO":"IAN LURIZ","DESTINATION":"MAIN OFFICE","EQUIPMENT / MATERIALS":"FUSION MACHINE","BRAND / MODEL":"SIGNAL FIRE_AI9","SERIAL NO.":"12345678","QTY":"1","STATUS":"GOOD CONDITION","REMARKS":"CALIBRATED","DATE ISSUED":"2026-10-14","REPAIR HISTORY":"","CALIBRATION HISTORY":""}];
const STATUSES=["GOOD CONDITION","DEFECTIVE","ONGOING REPAIR","ONGOING CALIBRATION","PARTS OUT"];
const FIELDS=[
["DATE TURNOVER","date"],["ACCOUNTABLE TO","text"],["DESTINATION","combo"],["EQUIPMENT / MATERIALS","combo"],["BRAND / MODEL","combo"],["SERIAL NO.","text"],["STATUS","select"],["REMARKS","remarks"],["DATE ISSUED","date"],["REPAIR HISTORY","date"],["CALIBRATION HISTORY","date"]];
let records=load(), editing=-1, activeView="dashboard";
function migrate(r){if(r["HISTORY OF REPAIR"]!==undefined&&r["REPAIR HISTORY"]===undefined)r["REPAIR HISTORY"]=r["HISTORY OF REPAIR"];if(r["HISTORY OF CALIBRATION"]!==undefined&&r["CALIBRATION HISTORY"]===undefined)r["CALIBRATION HISTORY"]=r["HISTORY OF CALIBRATION"];delete r["HISTORY OF REPAIR"];delete r["HISTORY OF CALIBRATION"];let st=String(r.STATUS||"").trim().toUpperCase();if(st==="DEPLOYED")r.STATUS="GOOD CONDITION";if(st==="FOR REPAIR")r.STATUS="ONGOING REPAIR";if(st==="FOR CALIBRATION")r.STATUS="ONGOING CALIBRATION";return r}
function readStore(k){try{let v=localStorage.getItem(k);if(v)return JSON.parse(v)}catch(e){}try{let n=JSON.parse(window.name||"{}");return n[k]||null}catch(e){return null}}
function writeStore(k,v){syncOut(k,v);let ok=false;try{localStorage.setItem(k,JSON.stringify(v));ok=true}catch(e){}try{let n={};try{n=JSON.parse(window.name||"{}")}catch(e){}n[k]=v;window.name=JSON.stringify(n)}catch(e){}return ok}
function load(){try{return (readStore("recab_records_v1")||SEED.map(x=>({...x}))).map(migrate)}catch(e){return SEED.map(x=>({...x}))}}
function save(){return writeStore("recab_records_v1",records)}
function norm(s){return String(s||"").trim().toUpperCase()}
function statusClass(s){s=norm(s);if(s==="GOOD CONDITION")return"good";if(s==="DEFECTIVE")return"defective";if(s==="ONGOING REPAIR")return"repair";if(s==="ONGOING CALIBRATION")return"calibration";return"parts"}
function countStatus(s){return records.filter(r=>norm(r.STATUS)===s).length}
function toast(msg){let t=document.getElementById("toast");t.textContent=msg;t.classList.add("show");setTimeout(()=>t.classList.remove("show"),2500)}
function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
