if(sortKey)filtered.sort((x,y)=>{let a=x[sortKey]||"",b=y[sortKey]||"";return (sortKey==="QTY"?(+a)-(+b):String(a).localeCompare(String(b),undefined,{numeric:true}))*sortDir});
let act=r=>`<td><div class="rowactions"><button class="iconbtn" onclick="editRecord(${r._i})">Details</button><button class="iconbtn" onclick="viewRecord(${r._i})">View</button>${hist?"":`<button class="iconbtn${r.DEPLOYED?" deployed":""}" onclick="deployRecord(${r._i})" title="${r.DEPLOYED?"Deployed — click to clear":"Deploy and print form"}" aria-label="Deploy" style="display:inline-flex;align-items:center;gap:6px;padding-left:10px;padding-right:11px;font-weight:700"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="display:block"><path d="M6 9V3h12v6"/><rect x="3" y="9" width="18" height="9" rx="2"/><rect x="7" y="14" width="10" height="7" rx="1" fill="#fff" fill-opacity=".15"/></svg><span>${r.DEPLOYED?"Deployed":"Deploy"}</span></button>`}<button class="iconbtn trashbtn" onclick="deleteRecord(${r._i})" title="Delete record" aria-label="Delete" style="display:inline-flex;align-items:center;padding-left:9px;padding-right:9px"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="display:block"><path d="M3 6h18"/><path d="M8 6V4h8v2"/><path d="M6 6l1 14h10l1-14"/><path d="M10 11v6M14 11v6"/></svg></button></div></td>`;
let eq=r=>`<td><div class="equip">${esc(r["EQUIPMENT / MATERIALS"]||"—")}</div><div class="subcell">${esc(r["BRAND / MODEL"]||"No model specified")}</div></td>`;
let pill=r=>hist?`<td><span class="pill ${statusClass(r.STATUS)} clickable" role="button" tabindex="0" title="Click to view or change status" onclick="openStatusMenu(event,${r._i})" onkeydown="if(event.key==='Enter')openStatusMenu(event,${r._i})">${esc(r.STATUS||"UNSPECIFIED")} <span class="caret">▾</span></span></td>`:`<td><span class="pill ${statusClass(r.STATUS)}">${esc(r.STATUS||"UNSPECIFIED")}</span></td>`;
document.getElementById("tableBody").innerHTML=filtered.map(r=>hist?`<tr>${eq(r)}<td>${esc(r["SERIAL NO."]||"—")}</td>${pill(r)}<td style="white-space:normal;min-width:200px;max-width:300px"><div class="remarkcell" title="${esc(r.REMARKS||"")}">${esc(r.REMARKS||"—")}</div></td><td style="white-space:normal;min-width:200px">${esc(r["REPAIR HISTORY"]||"—")}</td><td style="white-space:normal;min-width:200px">${esc(r["CALIBRATION HISTORY"]||"—")}</td>${act(r)}</tr>`:`<tr>${eq(r)}<td>${esc(r["SERIAL NO."]||"—")}</td><td>${esc(r["ACCOUNTABLE TO"]||"—")}</td><td>${esc(r.DESTINATION||"—")}</td>${pill(r)}<td>${esc(r["DATE ISSUED"]||"—")}</td>${act(r)}</tr>`).join("");
