function optList(h){let o=loadOpts(),saved=o[h]||[],hid=o["~"+h]||[];return [...new Set([...OPT_DEFAULTS[h],...saved,...records.map(r=>r[h]).filter(Boolean)])].filter(x=>!hid.includes(x)).sort()}
function optAdd(h,v){v=(v||"").trim().toUpperCase();if(!v)return "";let o=loadOpts();o[h]=[...new Set([...(o[h]||[]),v])];o["~"+h]=(o["~"+h]||[]).filter(x=>x!==v);writeStore("recab_opts_v1",o);return v}
function optRemove(h,v){let o=loadOpts();o[h]=(o[h]||[]).filter(x=>x!==v);o["~"+h]=[...new Set([...(o["~"+h]||[]),v])];writeStore("recab_opts_v1",o)}
function optRebuild(sel,v){let h=sel.dataset.manage||sel.name,list=optList(h);if(v&&!list.includes(v))list.push(v);sel.innerHTML='<option value="">— Select —</option>'+list.map(o=>`<option${o===v?" selected":""}>${esc(o)}</option>`).join("");sel.value=list.includes(v)?v:""}
