let iss=months.map(m=>cnt("DATE ISSUED",m)),act=months.map(m=>cnt("REPAIR HISTORY",m)+cnt("CALIBRATION HISTORY",m)),tot=iss.map((v,i)=>v+act[i]),max=Math.max(4,...tot),step=Math.ceil(max/4),top=step*4,X=i=>L+i*(W-L-R)/11,Y=v=>T+(H-T-B)*(1-v/top),base=H-B;
