function sha256(s){
 s=unescape(encodeURIComponent(s));
 var K=[],H=[],i,j,c,isC={},pc=0,mp=Math.pow(2,32);
 for(c=2;pc<64;c++){if(!isC[c]){for(i=0;i<313;i+=c)isC[i]=c;H[pc]=(Math.pow(c,.5)*mp)|0;K[pc++]=(Math.pow(c,1/3)*mp)|0}}
 H=H.slice(0,8);
 var ror=function(x,n){return(x>>>n)|(x<<(32-n))};
 var l=s.length*8,w=[];
 s+="\x80";while(s.length%64-56)s+="\x00";
 for(i=0;i<s.length;i++)w[i>>2]|=s.charCodeAt(i)<<((3-i%4)*8);
 w.push((l/mp)|0);w.push(l|0);
 for(j=0;j<w.length;j+=16){
  var W=w.slice(j,j+16),o=H.slice(0,8),a=H.slice(0,8);
  for(i=0;i<64;i++){
   var w15=W[i-15],w2=W[i-2];
   if(i>=16)W[i]=(W[i-16]+(ror(w15,7)^ror(w15,18)^(w15>>>3))+W[i-7]+(ror(w2,17)^ror(w2,19)^(w2>>>10)))|0;
   var e=a[4],t1=(a[7]+(ror(e,6)^ror(e,11)^ror(e,25))+((e&a[5])^(~e&a[6]))+K[i]+W[i])|0,
       t2=((ror(a[0],2)^ror(a[0],13)^ror(a[0],22))+((a[0]&a[1])^(a[0]&a[2])^(a[1]&a[2])))|0;
   a=[(t1+t2)|0,a[0],a[1],a[2],(a[3]+t1)|0,a[4],a[5],a[6]];
  }
  for(i=0;i<8;i++)H[i]=(o[i]+a[i])|0;
 }
 var out="";for(i=0;i<8;i++){out+=("00000000"+(H[i]>>>0).toString(16)).slice(-8)}
 return out;
}

/* ===== Access control (client-side) ===== */
const U_KEY="recab_users_v1",S_KEY="recab_session_v1";
let users=[],me=null,fails=0,lockUntil=0;
function rndSalt(){let a="";try{let b=new Uint8Array(12);crypto.getRandomValues(b);b.forEach(x=>a+=("0"+x.toString(16)).slice(-2))}catch(e){for(let i=0;i<24;i++)a+=Math.floor(Math.random()*16).toString(16)}return a}
function hashPw(p,salt){let h=sha256(salt+"|"+p);for(let i=0;i<3000;i++)h=sha256(h+salt);return h}
function mkUser(un,name,role,pw,must){let salt=rndSalt();return{u:un.toLowerCase(),name,role,salt,hash:hashPw(pw,salt),must:!!must,created:new Date().toISOString().slice(0,10)}}
function loadUsers(){let u=readStore(U_KEY);if(!Array.isArray(u)||!u.length){u=[mkUser("admin","Administrator","admin","admin123",true)];writeStore(U_KEY,u)}return u}
function saveUsers(){return writeStore(U_KEY,users)}
function getSess(){try{return sessionStorage.getItem(S_KEY)}catch(e){return window.__sess||null}}
function setSess(v){try{v?sessionStorage.setItem(S_KEY,v):sessionStorage.removeItem(S_KEY)}catch(e){window.__sess=v||null}}
function isAdmin(){return !!me&&me.role==="admin"}
function swapDashPanels(viewer){let a=document.querySelector(".dgrid.a>.panel:first-child"),c=document.querySelector(".dgrid.c>.panel:first-child");if(!a||!c||!!window.__dashSwapped===!!viewer)return;let t=document.createElement("span");a.replaceWith(t);c.replaceWith(a);t.replaceWith(c);window.__dashSwapped=!!viewer}
function applyRole(){swapDashPanels(!isAdmin());document.body.classList.toggle("role-user",!isAdmin());document.getElementById("navUsers").style.display=isAdmin()?"":"none";
 let n=(me.name||me.u).trim();document.getElementById("uName").textContent=n;document.getElementById("uRole").textContent=isAdmin()?"Admin":"User · view only";document.getElementById("uAv").textContent=n.split(/\s+/).map(x=>x[0]).join("").slice(0,2).toUpperCase()||"U"}
