function signOut(){if(window.sbOnLogout)sbOnLogout();if(window.spClose)spClose();me=null;setSess(null);closeAuthDlg();document.getElementById("overlay").classList.remove("show");closeStatusMenu();closeConfirm();document.body.classList.add("role-user");document.getElementById("lgUser").value="";document.getElementById("lgPass").value="";document.getElementById("lgErr").textContent="";document.getElementById("loginGate").style.display="flex";document.getElementById("lgUser").focus()}
function doLogin(){let now=Date.now(),err=document.getElementById("lgErr");if(now<lockUntil){err.textContent="Too many attempts. Try again in "+Math.ceil((lockUntil-now)/1000)+"s.";return}
 let un=document.getElementById("lgUser").value.trim().toLowerCase(),pw=document.getElementById("lgPass").value,u=users.find(x=>x.u===un);
 if(u&&un&&hashPw(pw,u.salt)===u.hash){fails=0;err.textContent="";document.getElementById("lgPass").value="";enter(u)}
 else{fails++;document.getElementById("lgPass").value="";if(fails>=5){lockUntil=Date.now()+30000;fails=0;err.textContent="Too many failed attempts. Locked for 30 seconds."}else err.textContent="Incorrect username or password."}}
