 document.body.appendChild(d);let go=()=>{let v={};fields.forEach(f=>v[f.id]=document.getElementById("ad_"+f.id).value);let e=onOk(v);if(e)document.getElementById("adErr").textContent=e;else closeAuthDlg()};
