function destClear(){dd.type="";dd.st="";dd.q="";renderDest()}
function renderDest(keepFocus){let o=document.getElementById("destModal");if(!o)return;
 const L=dd.list,STS=["GOOD CONDITION","DEFECTIVE","ONGOING REPAIR","ONGOING CALIBRATION","PARTS OUT"],SL={"GOOD CONDITION":"Good","DEFECTIVE":"Defective","ONGOING REPAIR":"Repair","ONGOING CALIBRATION":"Calibration","PARTS OUT":"Parts out"};
 let cs=k=>L.filter(r=>norm(r.STATUS)===k).length,dep=L.filter(r=>r.DEPLOYED).length,nTypes=[...new Set(L.map(r=>norm(r["EQUIPMENT / MATERIALS"])||"UNSPECIFIED"))];
 let types=nTypes.map(t=>({t,l:L.filter(r=>(norm(r["EQUIPMENT / MATERIALS"])||"UNSPECIFIED")===t)})).sort((a,b)=>b.l.length-a.l.length);
 let q=norm(dd.q),rows=L.map((r,i)=>({r,i})).filter(({r})=>(!dd.type||(norm(r["EQUIPMENT / MATERIALS"])||"UNSPECIFIED")===dd.type)&&(!dd.st||norm(r.STATUS)===dd.st)&&(!q||HEADERS.some(h=>norm(r[h]).includes(q))));
 let tile=(lab,n,c,note)=>`<div class="dm-tile" style="--c:${c}"><span>${lab}</span><b>${n}</b><small>${note}</small></div>`,pct=n=>L.length?Math.round(n/L.length*100)+"%":"0%";
 let h=`<div class="dm" tabindex="-1"><div class="dm-head"><div><div class="dm-eye">DESTINATION · EQUIPMENT DETAILS</div><h2>${esc(dd.site)}</h2><p>${L.length} unit${L.length===1?"":"s"} on record across ${types.length} equipment type${types.length===1?"":"s"} · ${dep} deployed</p></div><button type="button" class="dm-x" onclick="closeDest()" aria-label="Close details">&times;</button></div>
 <div class="dm-body">
 <div class="dm-tiles">${tile("Total units",L.length,"#8b5cf6","All records at this site")}${tile("Deployed",dep,"#c04bff",pct(dep)+" of total")}${tile("Good condition",cs("GOOD CONDITION"),"#2ff3c6",pct(cs("GOOD CONDITION"))+" operational")}${tile("Defective",cs("DEFECTIVE"),"#ff4d6d",cs("DEFECTIVE")?"Needs attention":"None reported")}${tile("Ongoing repair",cs("ONGOING REPAIR"),"#ff9a2e","Under repair")}${tile("Ongoing calibration",cs("ONGOING CALIBRATION"),"#22d3ee","Under calibration")}</div>
 <div class="dm-sec"><div class="dm-sech"><h3>Breakdown by equipment type</h3><span>Select a type to filter the list</span></div><div class="dm-types">${types.map(({t,l})=>`<button type="button" class="dm-type${dd.type===t?" on":""}" onclick="destSet('type',this.dataset.t)" data-t="${esc(t)}"><b>${esc(t)}</b><em>${l.length}</em>${segBar(l)}<span class="dm-mini">${STS.map(k=>{let c=l.filter(r=>norm(r.STATUS)===k).length;return c?`<i style="--c:${STATUS_COLORS[k]}"><u></u>${c} ${SL[k]}</i>`:""}).join("")}</span></button>`).join("")}</div></div>
 <div class="dm-sec"><div class="dm-sech"><h3>Equipment list</h3><span id="dmCount">Showing ${rows.length} of ${L.length}</span></div>
 <div class="dm-tools"><input class="dm-search" id="dmQ" type="search" placeholder="Search equipment, serial, person, remarks…" value="${esc(dd.q)}" oninput="dd.q=this.value;dd.__f=1;renderDest(true)" onfocus="dd.__f=1">${(dd.type||dd.st||dd.q)?`<button type="button" class="dm-clear" onclick="destClear()">Clear filters</button>`:""}</div>
 <div class="dm-tw"><table class="dm-table"><thead><tr><th>Equipment / model</th><th>Serial no.</th><th>Accountable to</th><th>Status</th><th>Date issued</th><th>Deployment</th><th></th></tr></thead><tbody>${rows.length?rows.map(({r,i})=>{let k=i,op=!!dd.open[k],nm=r["EQUIPMENT / MATERIALS"]||"—";return `<tr class="dm-row${op?" open":""}" onclick="destToggle(${k})" tabindex="0" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();destToggle(${k})}" aria-expanded="${op}"><td><div class="dm-eq">${esc(nm)}</div><div class="dm-sub">${esc(r["BRAND / MODEL"]||"No model recorded")}</div></td><td>${esc(r["SERIAL NO."]||"—")}</td><td>${esc(r["ACCOUNTABLE TO"]||"—")}</td><td><span class="pill ${PILL[norm(r.STATUS)]||"parts"}">${esc(r.STATUS||"—")}</span></td><td>${esc(r["DATE ISSUED"]||"—")}</td><td>${r.DEPLOYED?'<span class="dm-dep on">&#9679; Deployed</span>':'<span class="dm-dep">Not deployed</span>'}</td><td class="dm-car">${op?"&#9650;":"&#9660;"}</td></tr>${op?`<tr class="dm-x2"><td colspan="7"><div class="dm-det"><div><span>Date turnover</span><p>${esc(r["DATE TURNOVER"]||"—")}</p></div><div><span>Destination</span><p>${esc(r.DESTINATION||"—")}</p></div><div class="w"><span>Remarks</span><p>${esc(r.REMARKS||"—")}</p></div><div class="w"><span>Repair history</span><p>${esc(r["REPAIR HISTORY"]||"—")}</p></div><div class="w"><span>Calibration history</span><p>${esc(r["CALIBRATION HISTORY"]||"—")}</p></div></div></td></tr>`:""}`}).join(""):`<tr><td colspan="7" class="dm-empty">No equipment matches the current filters.</td></tr>`}</tbody></table></div></div>
 </div><div class="dm-foot"><span style="margin-right:auto">Tap a row to expand its full record</span>${isAdmin()?`<button type="button" class="btn primary" onclick="destOpenReg()">Open in register</button>`:""}<button type="button" class="btn" onclick="closeDest()">Close</button></div></div>`;
 let sc=o.querySelector(".dm-body"),top=sc?sc.scrollTop:0;o.innerHTML=h;let nb=o.querySelector(".dm-body");if(nb)nb.scrollTop=top;
 let qi=document.getElementById("dmQ");if(qi&&dd.__f){qi.focus();let n=qi.value.length;qi.setSelectionRange(n,n)}}

/* maximized By destination panel */
function destDetailName(site){let ix=(window.__destNames||[]).indexOf(site);if(ix<0){window.__destNames=(window.__destNames||[]).concat(site);ix=window.__destNames.length-1}destDetail(ix)}
function dmxKey(e){if(e.key==="Escape"&&document.getElementById("dmxModal")){e.stopPropagation();closeDestMax()}}
function closeDestMax(){let o=document.getElementById("dmxModal");if(o)o.remove();if(!document.getElementById("destModal"))document.body.style.overflow="";document.removeEventListener("keydown",dmxKey)}
function openDestMax(){closeDestMax();let m={};records.forEach(r=>{if(r.DESTINATION){let d=m[r.DESTINATION]||(m[r.DESTINATION]={t:0,o:0,f:0});d.t++;let k=norm(r["EQUIPMENT / MATERIALS"]);if(k==="OTDR")d.o++;if(k==="FUSION MACHINE")d.f++}});
 let list=Object.entries(m).sort((a,b)=>b[1].t-a[1].t),mx=list.length?list[0][1].t:1,sum=list.reduce((a,[,v])=>({t:a.t+v.t,o:a.o+v.o,f:a.f+v.f}),{t:0,o:0,f:0}),z=n=>`<span class="dchip${n?"":" zero"}">${n}</span>`;
 let o=document.createElement("div");o.id="dmxModal";o.className="dmov dmx";o.setAttribute("role","dialog");o.setAttribute("aria-modal","true");o.setAttribute("aria-label","By destination, maximized");
 o.innerHTML=`<div class="dm dmxbox" tabindex="-1"><div class="dm-head"><div><div class="dm-eye">DASHBOARD · BY DESTINATION</div><h2>Units per site</h2><p>${list.length} site${list.length===1?"":"s"} · ${sum.t} unit${sum.t===1?"":"s"} · select a site to see all of its equipment</p></div><button type="button" class="dm-x" onclick="closeDestMax()" aria-label="Restore panel" title="Restore"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 14h6v6"/><path d="M20 10h-6V4"/><path d="M14 10l7-7"/><path d="M3 21l7-7"/></svg></button></div>
 <div class="dm-body dmx-body">${list.length?`<div class="drow dhead"><span>SITE</span><span></span><span>OTDR</span><span>FUSION</span></div>`+list.map(([d,v])=>`<div class="drow dv dvrow" role="button" tabindex="0" data-site="${esc(d)}" onclick="destDetailName(this.dataset.site)" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();destDetailName(this.dataset.site)}" title="View all equipment at ${esc(d)}"><span class="dname">${esc(d)}</span><div class="dbar"><div style="width:${v.t/mx*100}%"></div></div>${z(v.o)}${z(v.f)}</div>`).join("")+`<div class="drow dv dmx-sum"><span class="dname">ALL SITES</span><span></span>${z(sum.o)}${z(sum.f)}</div>`:'<div class="dm-empty">No destinations yet</div>'}</div>
 <div class="dm-foot"><span style="margin-right:auto">Select a row to open its full equipment details</span><button type="button" class="btn" onclick="closeDestMax()">Restore</button></div></div>`;
 o.addEventListener("mousedown",e=>{if(e.target===o)closeDestMax()});document.body.appendChild(o);document.body.style.overflow="hidden";document.addEventListener("keydown",dmxKey);let x=o.querySelector(".dmxbox");if(x)x.focus()}
/* user management (admin) */
function renderUsers(){if(!isAdmin())return;document.getElementById("usersBody").innerHTML=users.map((x,i)=>`<tr><td><div class="equip">${esc(x.name||x.u)}</div></td><td>${esc(x.u)}</td><td><button type="button" class="pill clickable ${x.role==="admin"?"calibration":"good"}" onclick="uAccessMenu(${i},this)" aria-haspopup="listbox" title="Change access level">${x.role==="admin"?"ADMIN &middot; FULL CONTROL":"USER &middot; VIEW ONLY"}<span class="caret">&#9662;</span></button></td><td>${esc(x.created||"\u2014")}</td><td><div class="rowactions"><button class="iconbtn editbtn" onclick="uEdit(${i})" title="Edit name, username or password" aria-label="Edit account"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4z"/></svg><span>Edit</span></button><button class="iconbtn" onclick="uReset(${i})">Reset password</button>${x.u===me.u?"":`<button class="iconbtn trashbtn" onclick="uDel(${i})">Delete</button>`}</div></td></tr>`).join("")}
function closeAccMenu(){let m=document.getElementById("accMenu");if(m)m.remove();document.removeEventListener("mousedown",accOutside,true);document.removeEventListener("keydown",accKey,true);window.removeEventListener("scroll",closeAccMenu,true);window.removeEventListener("resize",closeAccMenu)}
function accOutside(e){let m=document.getElementById("accMenu");if(m&&!m.contains(e.target))closeAccMenu()}
function accKey(e){if(e.key==="Escape")closeAccMenu()}
function uAccessMenu(i,btn){if(!isAdmin())return;let open=document.getElementById("accMenu"),same=open&&open.dataset.i==String(i);closeAccMenu();if(same)return;let x=users[i],r=btn.getBoundingClientRect(),m=document.createElement("div");m.id="accMenu";m.dataset.i=i;m.setAttribute("role","listbox");
 m.innerHTML=[["admin","ADMIN &middot; FULL CONTROL","Can add, edit, delete and manage accounts","#22d3ee"],["user","USER &middot; VIEW ONLY","Can only view records","#2ff3c6"]].map(o=>`<button type="button" role="option" aria-selected="${x.role===o[0]}" class="${x.role===o[0]?"cur":""}" style="--c:${o[3]}" onclick="uSetRole(${i},'${o[0]}')"><i></i><span><b>${o[1]}</b><small>${o[2]}</small></span><em>&#10003;</em></button>`).join("");
 document.body.appendChild(m);let w=m.offsetWidth,h=m.offsetHeight,left=Math.min(r.left,window.innerWidth-w-10),top=r.bottom+6;if(top+h>window.innerHeight-10)top=Math.max(10,r.top-h-6);m.style.left=Math.max(10,left)+"px";m.style.top=top+"px";
 setTimeout(()=>{document.addEventListener("mousedown",accOutside,true);document.addEventListener("keydown",accKey,true);window.addEventListener("scroll",closeAccMenu,true);window.addEventListener("resize",closeAccMenu)},0)}
function uSetRole(i,to){closeAccMenu();if(!isAdmin())return;let x=users[i];if(!x||x.role===to)return;if(to==="user"&&adminCount()<=1){toast("There must be at least one admin");return}if(!confirm("Change "+x.u+" to "+(to==="admin"?"ADMIN (full control)":"USER (view only)")+"?"))return;x.role=to;saveUsers();if(x.u===me.u){applyRole();if(to==="user"){document.querySelector('.nav button[data-view="dashboard"]').click()}}renderUsers();toast("Access updated for "+x.u)}
function uEdit(i){if(!isAdmin())return;let x=users[i];if(!x)return;authDlg("Edit account","Change the name, username or password. Leave the password blank to keep it unchanged.",[{id:"name",label:"Full name",value:x.name||""},{id:"un",label:"Username",value:x.u},{id:"pw",label:"New password (optional)",type:"password",ph:"Leave blank to keep current"}],"Save changes",v=>{
 let nm=v.name.trim(),un=v.un.trim().toLowerCase();if(!nm)return"Enter the full name.";if(!/^[a-z0-9._-]{3,30}$/.test(un))return"Username: 3-30 letters, numbers, . _ -";if(users.some((y,j)=>j!==i&&y.u===un))return"That username is already taken.";if(v.pw){let p=pwProblem(v.pw);if(p)return p}
 let wasMe=x.u===me.u,changed=nm!==x.name||un!==x.u||!!v.pw;if(!changed)return;x.name=nm;x.u=un;if(v.pw){x.salt=rndSalt();x.hash=hashPw(v.pw,x.salt);x.must=!wasMe}
 saveUsers();if(wasMe){me=x;setSess(x.u);applyRole()}renderUsers();toast("Account updated for "+un)})}
function adminCount(){return users.filter(x=>x.role==="admin").length}
function uNew(){if(!isAdmin())return;authDlg("Create account","Users can view records only. Admins have full control.",[{id:"name",label:"Full name"},{id:"un",label:"Username",ph:"letters, numbers, . _ -"},{id:"role",label:"Access level",options:[["user","User (view only)"],["admin","Admin (full control)"]]},{id:"pw",label:"Password",type:"password"}],"Create account",v=>{
 let un=v.un.trim().toLowerCase(),nm=v.name.trim();if(!nm)return"Enter the full name.";if(!/^[a-z0-9._-]{3,30}$/.test(un))return"Username: 3-30 letters, numbers, . _ -";if(users.some(x=>x.u===un))return"That username is already taken.";let p=pwProblem(v.pw);if(p)return p;
 users.push(mkUser(un,nm,v.role==="admin"?"admin":"user",v.pw,true));saveUsers();renderUsers();toast("Account created for "+nm)})}
function uReset(i){if(!isAdmin())return;let x=users[i];authDlg("Reset password",x.name+" ("+x.u+") will use this password at next sign-in.",[{id:"pw",label:"Password",type:"password"}],"Reset password",v=>{let p=pwProblem(v.pw);if(p)return p;x.salt=rndSalt();x.hash=hashPw(v.pw,x.salt);x.must=true;if(x.u===me.u)me=x;saveUsers();renderUsers();toast("Password reset for "+x.u)})}
function uRole(i){if(!isAdmin())return;let x=users[i],to=x.role==="admin"?"user":"admin";if(to==="user"&&adminCount()<=1){toast("There must be at least one admin");return}if(!confirm("Change "+x.u+" to "+(to==="admin"?"ADMIN (full control)":"USER (view only)")+"?"))return;x.role=to;saveUsers();if(x.u===me.u){applyRole();if(to==="user"){document.querySelector('.nav button[data-view="dashboard"]').click()}}renderUsers();toast("Access updated for "+x.u)}
function uDel(i){if(!isAdmin())return;let x=users[i];if(x.u===me.u){toast("You cannot delete your own account");return}if(x.role==="admin"&&adminCount()<=1){toast("There must be at least one admin");return}if(!confirm("Delete account "+x.u+"? This cannot be undone."))return;users.splice(i,1);saveUsers();renderUsers();toast("Account deleted")}

function recordSheet(i){let r=records[i];if(!r)return;let now=new Date(),ymd=now.toISOString().slice(0,10).replace(/-/g,""),ref="REC-"+ymd+"-"+String(i+1).padStart(3,"0"),st=r.STATUS||"UNSPECIFIED",col=STATUS_COLORS[norm(st)]||"#8d8ca8",logo=document.querySelector(".brandlogo").src,
 v=x=>{x=String(x==null?"":x).trim();return x?esc(x):"\u2014"},c=(k,x)=>`<td class="k">${k}</td><td class="v">${v(x)}</td>`,
 rem=String(r.REMARKS||"").trim(),who=me?(me.name||me.u):"";
 document.getElementById("printArea").innerHTML=`<div class="ps rs">
<div class="rs-head"><div><small>IT OPERATIONS &middot; ASSET CONTROL</small><h1>EQUIPMENT RECORD SHEET</h1><p>Technical Equipment Tracker &middot; Equipment &amp; Materials</p></div><img class="rs-logo" src="${logo}" alt="Jedlian Communication"></div>
<div class="rs-bar"></div>
<div class="rs-meta"><div><span>Record no.</span><b>${ref}</b></div><div><span>Date generated</span><b>${now.toLocaleDateString("en-PH",{year:"numeric",month:"long",day:"2-digit"})}</b></div><div><span>Current status</span><b><i class="rs-dot" style="background:${col}"></i>${esc(st)}</b></div><div><span>Deployment</span><b>${r.DEPLOYED?"DEPLOYED":"NOT DEPLOYED"}</b></div></div>
<h2><i>1</i>Equipment identification</h2><table><tr>${c("Equipment / Materials",r["EQUIPMENT / MATERIALS"])}${c("Brand / Model",r["BRAND / MODEL"])}</tr><tr>${c("Serial No.",r["SERIAL NO."])}${c("Quantity",r.QTY||"1")}</tr></table>
<h2><i>2</i>Assignment &amp; accountability</h2><table><tr>${c("Accountable to",r["ACCOUNTABLE TO"])}${c("Destination",r.DESTINATION)}</tr><tr><td class="k">Date turnover</td><td class="v">${fmtD(r["DATE TURNOVER"])}</td><td class="k">Date issued</td><td class="v">${fmtD(r["DATE ISSUED"])}</td></tr></table>
<h2><i>3</i>Service history</h2><table><tr><td class="k">Repair history</td><td class="v">${fmtD(r["REPAIR HISTORY"])}</td><td class="k">Calibration history</td><td class="v">${fmtD(r["CALIBRATION HISTORY"])}</td></tr></table>
<h2><i>4</i>Remarks</h2><div class="rs-rem">${rem?esc(rem):"No remarks recorded."}</div>
<h2><i>5</i>Inspection checklist</h2><div class="rs-chk"><div><i class="rs-box"></i>Physical condition checked</div><div><i class="rs-box"></i>Accessories complete</div><div><i class="rs-box"></i>Powers on / functional test passed</div><div><i class="rs-box"></i>Calibration is current</div><div><i class="rs-box"></i>Serial number verified</div><div><i class="rs-box"></i>Cleaned and ready for use</div></div>
<h2><i>6</i>Additional notes</h2><div class="rs-lines"><div></div><div></div><div></div></div>
<div class="ps-sign"><div><span class="ps-name">${esc(who)}</span><i></i><b>Prepared by</b>IT Personnel<em>Date: ______________</em></div><div><span class="ps-name"></span><i></i><b>Checked by</b>Name / Signature<em>Date: ______________</em></div><div><span class="ps-name"></span><i></i><b>Approved by</b>Name / Signature<em>Date: ______________</em></div></div>
<div class="ps-foot"><span>IT Equipment Monitoring System &middot; Confidential &mdash; for internal use only</span><span>${ref} &middot; Printed ${now.toLocaleString("en-PH")}</span></div></div>`;window.print()}
